    while true do
      draw(); local e={os.pullEventRaw()}
      if e[1]=="terminate" then break end
      if e[1]=="timer" and e[2]==timer then receiver.tick(); timer=os.startTimer(0.25) end
      if e[1]=="peripheral" then cast.open(o.peripheral,o.rednet) end
